// 原Talk和真正双方Action后才产生回答；组件显式推进/释放不代正式World phase或GUI验收。
#define main original_appointment_inquiry_action_fixture_not_executed
#include "personal_appointment_test.cpp"
#undef main
#include "resident/domains/interaction/contact_inquiries/contact_inquiry.hpp"
namespace {
struct InquiryFixture:AppointmentFixture{
    FamilyDeathOriginRead deaths=[](const StableId&)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,std::nullopt,{}};};
    ContactInquiryCatalog inquiries;ContactInquiryState state;
    InquiryFixture(){inquiries.policies.push_back({"where_player","sender","player","sender","appointments","meet","share_last_seen",1});}
    AppointmentContactHistory appointments_read(){return {interaction,ic,appointments,appointment_state,deaths};}
    StableId begin_inquiry(){talk("meet","stranger");auto q=preview_contact_inquiry(common,interaction,ic,access,inquiries,state,"stranger",{"where_player"});require(q.ok,"actual provider author source:"+q.error.original.code);auto result=start_contact_inquiry_in_candidate(common,interaction,ic,access,inquiries,state,q.value);require(result.ok,"actual inquiry action:"+result.error.original.code);return result.value;}
    Status valid_inquiry(){auto old=appointments_read();KnownContactLocationAccess read{common,*shared,&old,nullptr};return validate_contact_inquiries(read,interaction,ic,inquiries,state,deaths);}
    ContactInquiryCompletion finish_inquiry(const StableId& id){ActionMutation step;step.action=*common.action(id);step.remaining_ticks=0;require(common.apply_action(step).ok,"actual remaining tick decrement");DynamicStepInput phase{common.tick(),common.tick()+1};auto old=appointments_read();KnownContactLocationAccess read{common,*shared,&old,nullptr};auto done=finish_contact_inquiry_in_candidate(common,interaction,ic,access,inquiries,state,read,*common.action(id),phase);require(done.ok,"real answer completion:"+done.error.original.code);require(validate_contact_inquiries(read,interaction,ic,inquiries,state,deaths,&phase).ok,"explicit phase permits only exact just-completed action");ActionMutation erase;erase.kind=ActionMutation::Kind::erase;erase.action.id=id;require(common.apply_action(erase).ok,"normal action release");for(const auto* participant:{"sender","stranger"})common.state().actors.find(participant)->action_id.clear();common.state().identity.tick=phase.to_tick;require(valid_inquiry().ok,"cold after original release/clock:"+valid_inquiry().error.original.code);return done.value;}
};
}
#ifndef HANMO_CONTACT_INQUIRY_ACTION_TEST_LIBRARY
int main(){try{
    InquiryFixture f;auto known=f.accept();f.leave();const auto before=encode_common_state(f.common.state());auto action=f.begin_inquiry();require(f.state.finished.empty()&&f.common.actor("sender")->action_id==action&&f.common.actor("stranger")->action_id==action&&f.valid_inquiry().ok,"quote/start expose no answer while original participants are really occupied");auto done=f.finish_inquiry(action);require(done.success,"substantive real meeting completed");const auto& reply=*f.state.finished.find(done.fact_id);require(reply.reply_kind=="known"&&reply.answer&&reply.answer->source_fact_id==known&&reply.answer->observed_tick==10&&reply.answer->learned_tick==11,"last seen time and later learned time remain distinct");require(compare_boundary(*before.find("wallets"),*encode_common_state(f.common.state()).find("wallets")).exact()&&compare_boundary(*before.find("inventories"),*encode_common_state(f.common.state()).find("inventories")).exact(),"inquiry neither charges money nor creates goods");require(!preview_contact_inquiry(f.common,f.interaction,f.ic,f.access,f.inquiries,f.state,"stranger",{"where_player"}).ok,"same original session cannot fabricate repeated independent answers");auto saved=f.state;f.state.finished.find(done.fact_id)->answer->place_id="nowhere";require(!f.valid_inquiry().ok,"saved location must match original observed source");f.state=saved;f.state.finished.find(done.fact_id)->answer->observed_tick=11;require(!f.valid_inquiry().ok,"completion does not refresh old observed time");f.state=saved;f.state.finished.find(done.fact_id)->reply_kind="unknown";f.state.finished.find(done.fact_id)->answer.reset();require(!f.valid_inquiry().ok,"known original source cannot be removed to fake never knew");f.state=saved;
    InquiryFixture unknown;auto unknown_action=unknown.begin_inquiry();auto unknown_done=unknown.finish_inquiry(unknown_action);const auto& u=*unknown.state.finished.find(unknown_done.fact_id);require(unknown_done.success&&u.reply_kind=="unknown"&&!u.answer,"honest unknown is a completed meeting without made-up position");
    InquiryFixture declined;declined.inquiries.policies.front().disclosure="decline";auto declined_action=declined.begin_inquiry();auto declined_done=declined.finish_inquiry(declined_action);const auto& d=*declined.state.finished.find(declined_done.fact_id);require(declined_done.success&&d.reply_kind=="declined"&&!d.answer,"explicit refusal does not leak whether provider has other knowledge");
    InquiryFixture interrupted;interrupted.accept();interrupted.leave();auto failed_action=interrupted.begin_inquiry();interrupted.shared->places.insert("elsewhere",{"elsewhere","town",{}});interrupted.common.state().actors.find("sender")->location=SettlementLocation{"town","elsewhere"};auto failed=interrupted.finish_inquiry(failed_action);const auto& failure=*interrupted.state.finished.find(failed.fact_id);require(!failed.success&&failure.reply_kind.empty()&&!failure.answer,"departed provider never discloses answer on failed action");
    InquiryFixture overflow;overflow.talk("meet","stranger");auto q=preview_contact_inquiry(overflow.common,overflow.interaction,overflow.ic,overflow.access,overflow.inquiries,overflow.state,"stranger",{"where_player"});require(q.ok,"valid source before late ID failure");overflow.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;const auto original=encode_common_state(overflow.common.state());const auto original_state=overflow.state;auto point=overflow.common.begin_savepoint();require(point.ok,"component savepoint");auto rejected=start_contact_inquiry_in_candidate(overflow.common,overflow.interaction,overflow.ic,overflow.access,overflow.inquiries,overflow.state,q.value);require(!rejected.ok&&!overflow.common.actor("stranger")->action_id.empty(),"late fact allocator error follows actual occupation");require(overflow.common.rollback_savepoint(point.value).ok,"component rollback");overflow.state=original_state;require(compare_boundary(original,encode_common_state(overflow.common.state())).exact(),"outer candidate restores both people and action after late failure");
    std::cout<<"CONTACT_INQUIRY_ACTION: actual Talk/action/source, unknown/refusal, cold source and component rollback; World unrun\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#endif
